    {
      "action_name": "auto-doInitializeDevice",
      "description": "初始化设备，开始其基本工作状态。",
      "description_en": "Initialize the device and bring it into its basic operating state."
    },
    {
      "action_name": "auto-doShutdownDevice",
      "description": "关闭设备，结束其运行状态。",
      "description_en": "Shut down the device and end its operating state."
    }
  ],
  "tag_hints": [
    "generic lab device",
    "hardware lifecycle",
    "device initialization",
    "device shutdown",
    "instrument debugging"
  ]
}

